-- ----------------------------
-- Table structure for table small_cell_param_group
-- ----------------------------
DROP TABLE IF EXISTS `small_cell_param_group`;
CREATE TABLE `small_cell_param_group` (
  `id` int NOT NULL,
  `param_name` varchar(60) DEFAULT NULL,
  `keyword` varchar(50) DEFAULT NULL,
  `v_lst` varchar(2) DEFAULT 'N',
  `v_mod` varchar(2) DEFAULT 'N',
  `v_add` varchar(2) DEFAULT 'N',
  `v_rmv` varchar(2) DEFAULT 'N',
  `parent_id` int NOT NULL,
  `param_version` varchar(45) DEFAULT NULL COMMENT '参数版本，与small_cell_param表中的参数版本相对应',
  `add_path` varchar(200) DEFAULT NULL COMMENT '如果v_add列为Y，则此列存储执行AddObject时下发的参数路径；否则，该列应为空。执行DeleteObject命令时，下发的参数也是这个字段。',
  `param_name_en` varchar(60) DEFAULT '' COMMENT '英文名称',
  `mobile_support` char(4) DEFAULT 'Y' COMMENT '移动版支持配置，Y --支持，N--不支持',
  `broadband_support` char(4) DEFAULT 'Y' COMMENT '宽带版支持配置，Y --支持，N--不支持',
  `platform_support` varchar(5) DEFAULT NULL,
  `cell_number` int DEFAULT '1',
  `cell_index_location` int DEFAULT '0' COMMENT '小区索引位置',
  `second_confirm` char(1) DEFAULT NULL,
  `confirm_en` varchar(1000) DEFAULT NULL,
  `confirm_cn` varchar(1000) DEFAULT NULL,
  `dis_order` tinyint unsigned DEFAULT '1',
  PRIMARY KEY (`id`),
  UNIQUE KEY `id` (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb3 AVG_ROW_LENGTH=327;

-- ----------------------------
-- Records of small_cell_param_group
-- ----------------------------
